     assert (site/p).read_bytes()==z.read(p)
   result['installs'][mode+':'+kind]={'package_files':len(installed),'record_rows':len(ir),'record':info(record),'venv':str(venv),'payload_and_metadata_exact':True}
  result['packages'][kind]={'commit':commits[kind],'git_archive_command':command,'source_archive':info(root/(kind+'-source.tar')),'wheel':info(wheel),'version':metadata['Version'],'requires_dist':metadata.get_all('Requires-Dist',[]),'python_files':sum(p.endswith('.py') for p in actual),'resource_files':sum(not p.endswith('.py') for p in actual),'all_payload_bytes_exact_from_git':True,'wheel_record_rows':len(rows),'wheel_record_sha256':sha(z.read(dist+'/RECORD'))}
